# ---------- 2. Build DataFrame ----------
df = pd.DataFrame({
    "date": pd.to_datetime(dates, format="%Y-%m-%d"),
    "Pettah": [float(x) for x in pettah_prices],
    "Dambulla": [float(x) for x in dambulla_prices]
})

# ---------- 3. Remove or Aggregate Duplicates ----------
# Option A: keep last record for duplicate dates
# df = df.drop_duplicates(subset=["date"], keep="last")

# Option B: average values for duplicate dates (better for prices)
df = df.groupby("date", as_index=False).mean()

# ---------- 4. Fill Missing Dates ----------
all_days = pd.date_range(start=df["date"].min(), end=df["date"].max())
df = df.set_index("date").reindex(all_days).reset_index()
df = df.rename(columns={"index": "date"})

# forward fill missing values
df["Pettah"].fillna(method="ffill", inplace=True)
df["Dambulla"].fillna(method="ffill", inplace=True)

# ---------- 5. Extract Features ----------
df["year"] = df["date"].dt.year
df["month"] = df["date"].dt.month
df["day"] = df["date"].dt.day
df["day_of_week"] = df["date"].dt.dayofweek  # Monday=0, Sunday=6

# ---------- 6. Save ----------
output_file = "wholesale_prices_ml.csv"
df.to_csv(output_file, index=False)

